const mongoose = require("mongoose");

const userSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: true,
    },
    email: {
      type: String,
      required: true,
      unique: true,
    },
    password: {
      type: String,
      required: true,
    },
    image: {
      type: String,
      default:
        "data:image/png;base64,",
    },
    address: {
      type: Object,
      default: { line: "", line: "" },
    },
    gender: {
      type: String,
      default: "Not Selected",
    },
    dob: {
      type: String,
      default: "Not Selected",
    },
    phone: {
      type: String,
      default: "000000000",
    },
    // إضافة حقول الدورات
    courses: [
      {
        courseId: {
          type: mongoose.Schema.Types.ObjectId,
          ref: "course",
        },
        enrolledAt: {
          type: Date,
          default: Date.now,
        },
        progress: {
          type: Number,
          default: 0,
          min: 0,
          max: 100,
        },
        completedLessons: [
          {
            lessonId: mongoose.Schema.Types.ObjectId,
            completedAt: Date,
          },
        ],
        lastAccessed: {
          type: Date,
        },
      },
    ],
    isPremium: {
      type: Boolean,
      default: false,
    },
    subscriptionExpiry: {
      type: Date,
    },
    totalSpentOnCourses: {
      type: Number,
      default: 0,
    },
    createdAt: {
      type: Date,
      default: Date.now,
    },
    updatedAt: {
      type: Date,
      default: Date.now,
    },
  },
  { timestamps: true }
);

const userModel = mongoose.models.user || mongoose.model("user", userSchema);
module.exports = userModel;
